import{_ as a,C as s,o,c as n,a2 as t,E as i}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Reprendre un projet existant","description":"","frontmatter":{"title":"Reprendre un projet existant"},"headers":[],"relativePath":"guide/adopt.md","filePath":"guide/adopt.md"}'),l={name:"guide/adopt.md"};function u(p,e,d,c,g,m){const r=s("Capture");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="reprendre-un-projet-existant" tabindex="-1">Reprendre un projet existant <a class="header-anchor" href="#reprendre-un-projet-existant" aria-label="Permalink to &quot;Reprendre un projet existant&quot;">​</a></h1><p>Cet assistant fait entrer dans Effortless un dépôt qui existe déjà et qui n&#39;a jamais été suivi par Effortless (un projet « brownfield »). Il pose l&#39;ossature OPALE, regroupe le code et aligne le projet sur le schéma courant, en quatre étapes.</p><p>Avant de commencer, décidez du mode de travail et de l&#39;organisation du code — en particulier si votre dépôt doit garder sa structure ou s&#39;appuie sur des sources partagées : voir <a href="/Effortless/guide/setup.html">Choisir son organisation</a>.</p><h2 id="lancer-la-reprise" tabindex="-1">Lancer la reprise <a class="header-anchor" href="#lancer-la-reprise" aria-label="Permalink to &quot;Lancer la reprise&quot;">​</a></h2><p>Dans le sélecteur, cliquez sur <strong>Reprendre un projet existant</strong> et choisissez le dossier du projet. L&#39;assistant s&#39;ouvre ensuite sur ce dossier ; son chemin est rappelé sous le titre de chaque étape.</p>',5)),i(r,{name:"assistant-reprise",alt:"L'assistant de reprise, étape Détecter : simulation, aperçu et bouton Appliquer"}),e[1]||(e[1]=t('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>En haut</strong> : quatre étapes numérotées et la ligne « Reprendre un projet existant · Détecter (1/4) », puis une barre de progression.</li><li><strong>Au centre</strong> : le titre et l&#39;explication de l&#39;étape, ses réglages, puis deux boutons : <strong>Simuler (dry-run)</strong> et <strong>Appliquer</strong>.</li><li><strong>En bas</strong> : <strong>Précédent</strong> à gauche ; <strong>Fermer</strong> et <strong>Suivant</strong> à droite, <strong>Terminer</strong> à la dernière étape.</li></ul><h2 id="simuler-puis-appliquer" tabindex="-1">Simuler, puis appliquer <a class="header-anchor" href="#simuler-puis-appliquer" aria-label="Permalink to &quot;Simuler, puis appliquer&quot;">​</a></h2><p>Chaque étape se joue deux fois :</p><ol><li><strong>Simuler (dry-run)</strong> montre ce qui serait fait, sans rien écrire. Le résultat s&#39;affiche dans <strong>Aperçu (simulation)</strong>.</li><li><strong>Appliquer</strong> exécute réellement l&#39;étape. Il reste grisé tant que la simulation n&#39;a pas réussi ; l&#39;écran le rappelle : « Simulez d’abord pour débloquer l’exécution. » Le résultat s&#39;affiche dans <strong>Résultat de l’exécution</strong>, et l&#39;étape est marquée « Étape appliquée ✓ ».</li></ol><p><strong>Suivant</strong> ne s&#39;active qu&#39;une fois l&#39;étape appliquée : aucune étape ne se passe.</p><h2 id="les-quatre-etapes" tabindex="-1">Les quatre étapes <a class="header-anchor" href="#les-quatre-etapes" aria-label="Permalink to &quot;Les quatre étapes&quot;">​</a></h2><ol><li><strong>Détecter</strong> : analyse la pile et l&#39;arborescence du projet, puis met en place l&#39;ossature OPALE. La case « Forcer la ré-initialisation » sert si le dossier contient déjà une configuration Effortless : elle en garde une sauvegarde <code>.bak</code> avant de la refaire.</li><li><strong>Planifier</strong> : applique le plan de déplacements détecté à l&#39;étape précédente. Lisez la simulation pour voir chaque mouvement avant de l&#39;exécuter.</li><li><strong>Regrouper le code</strong> : rassemble le code de la racine sous <code>codebase/&lt;stack&gt;/</code>. Renseignez d&#39;abord l&#39;<strong>Identifiant de la stack cible</strong> (par exemple <code>app</code>, <code>api</code>, <code>desktop</code>) : sans lui, les boutons restent grisés.</li><li><strong>Finaliser</strong> : déroule les migrations pour aligner le projet sur le schéma courant d&#39;Effortless.</li></ol><h2 id="terminer" tabindex="-1">Terminer <a class="header-anchor" href="#terminer" aria-label="Permalink to &quot;Terminer&quot;">​</a></h2><p>À la quatrième étape, <strong>Terminer</strong> ouvre le projet dans un onglet. <strong>Fermer</strong> quitte l&#39;assistant à tout moment et vous ramène au sélecteur ; les étapes déjà appliquées restent appliquées.</p><h2 id="conseil" tabindex="-1">Conseil <a class="header-anchor" href="#conseil" aria-label="Permalink to &quot;Conseil&quot;">​</a></h2><p>Travaillez sur un dépôt propre et commité : l&#39;étape <strong>Regrouper le code</strong> déplace des fichiers.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Les mêmes étapes existent en verbes MCP, chacune avec son mode simulation : <code>effortless_migrate_init</code>, <code>effortless_migrate_apply</code>, <code>effortless_codebase_relocate</code> et <code>effortless_migrate</code>.</p>',14))])}const f=a(l,[["render",u]]);export{q as __pageData,f as default};
